INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-2-invu', 'Hunters & Referidos INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('El Uso de WhatsApp para Avanzar la Venta', 'En Latinoamérica, WhatsApp es el canal de comunicación preferido. El vendedor debe ser breve, educativo y dejar una pregunta de avance. El objetivo no es cerrar en WhatsApp, sino avanzar a una llamada o reunión. El mensaje debe conectar con el dolor del cliente y ofrecer valor inmediato.', '"Hola [nombre], vi tu consulta sobre INVU. Entendemos que cada negocio en Latinoamérica tiene sus propias necesidades. ¿Me puedes contar cuántos locales tienes y qué sistema usas hoy? Con eso te comparto casos de éxito de negocios similares al tuyo en tu país." El cliente responde y el vendedor agenda una llamada. El WhatsApp es la puerta de entrada.', 1),
('La Llamada de 20 Minutos que Cierra', 'En una llamada de ventas en Latinoamérica, el vendedor debe controlar el ritmo: 5 minutos de diagnóstico, 5 de educación, 5 de comparación, 5 de construcción de valor, y cerrar con una pregunta de avance. La llamada no es una presentación de producto; es una solución de problemas. El objetivo es terminar con una reunión agendada o una decisión de compra.', 'Un vendedor llama a un dueño de restaurante en Lima. En 5 minutos, diagnostica: 2 locales, sistema básico, paga Nubefact. En 5 minutos, educa sobre FE nativa. En 5 minutos, compara: S/450 vs S/350. En 5 minutos, construye valor: ahorro de mermas y comisiones. Cierra: "¿Qué día te acomoda para la demo?" El cliente agenda. La llamada de 20 minutos avanza la venta.', 2),
('La Demo Presencial que Conecta con el Espacio del Cliente', 'En una reunión presencial en Latinoamérica, el vendedor debe llevar una demostración física del sistema, preferiblemente en el equipo del cliente. La demo no es un recorrido por todas las funcionalidades; es una conexión con el espacio del cliente. Se muestra cómo INVU resolvería los dolores específicos identificados en el diagnóstico. Se invita al cliente a tocar el sistema y hacer preguntas.', 'Un vendedor visita un restaurante en Bogotá. Lleva una tablet con INVU instalado. No hace una demo genérica; muestra cómo centralizaría los 2 locales del cliente, cómo el KDS organizaría la cocina, cómo el QR agilizaría los pedidos en mesa. El cliente toca la tablet, ve su propio menú cargado, y visualiza su operación con INVU. La demo termina con una cotización y un plan de implementación.', 3),
('El Caso del Restaurante con Delivery y Ecommerce', 'Un restaurante con 2 locales, facturación de S/150,000, delivery por apps y ecommerce desconectado del sistema, es un cliente ideal para INVU. El vendedor debe mostrar que INVU integra todo: POS, inventario, delivery, ecommerce y fidelización en una sola plataforma. El argumento es que el costo de INVU es menor que el costo de mantener sistemas separados y que las herramientas de INVU generarán ingresos adicionales que cubrirán la inversión.', 'El vendedor dice: "Con INVU, delivery y ecommerce se integran automáticamente. Los pedidos entran solos, el inventario se actualiza sin intervención, y tú tienes datos en tiempo real desde tu celular. El ahorro de tiempo y la reducción de errores justifican la inversión. Te propongo que hagamos una demostración enfocada en cómo integrarías delivery, ecommerce y tus 2 locales."', 4),
('El Manejo de la Objeción "Es Caro para Mi Tamaño"', 'El cliente que dice "es caro para mi tamaño de negocio" está comparando el precio de INVU con su facturación actual, sin ver el valor a largo plazo. El vendedor debe validar la preocupación, educar sobre la escalabilidad de INVU, comparar con el costo de sistemas separados, construir valor mostrando el ahorro en tiempo y el incremento en ventas, y cerrar con una pregunta de avance.', '"Entiendo que el presupuesto es importante. INVU es escalable: empiezas con lo que necesitas hoy: POS e inventario. Cuando crezcas, activas delivery, ecommerce, fidelización. No pagas por lo que no usas. Un sistema simple te va a costar menos ahora, pero te va a dar problemas de integración. Cuando necesites delivery o ecommerce, vas a tener que pagar sistemas separados. INVU ya los tiene integrados."', 5),
('El Manejo de la Objeción "Lo Voy a Pensar"', 'El cliente que dice "lo voy a pensar" está en el momento de indecisión. El vendedor debe validar que es normal, educar sobre el costo de postergar (tiempo, dinero, oportunidades perdidas), comparar cada mes sin integración con la inversión, construir valor ofreciendo una demo sin compromiso, y cerrar con una pregunta de avance para agendar la reunión.', '"Es normal. Lo que muchos clientes me dicen es que después de pensar, se dan cuenta de que el costo de no tener integración es mayor que el costo de implementarla. Cada mes sin integración es un mes de doble trabajo, inventario desactualizado y oportunidades perdidas. Pensarlo cuesta tiempo y dinero. No te pido que decidas hoy. Te pido que le des la oportunidad a INVU de demostrarte su valor en una reunión."


# PÍLDORAS DE CONOCIMIENTO - INVU POS HUNTERS', 6),
('El Rol del Hunter – Cazador, No Esperador', 'El Hunter no espera leads; sale a la calle a identificar negocios, contactar tomadores de decisión, presentar el valor de INVU y cerrar ventas. El Hunter es un cazador de oportunidades que construye su propio mercado. Su ingreso depende directamente de su esfuerzo: 15 visitas/semana, 10 reuniones con decisores, 5 demos/mes, 2-3 cierres/mes. El que no visita, no vende.', 'Un Hunter inicia su semana con una agenda de 15 visitas a restaurantes. No espera que el teléfono suene; sale a la calle, entra a los locales, identifica al dueño o gerente, y hace su pitch. En la primera semana, logra 5 reuniones. En la segunda, 3 demos. En la tercera, 2 cierres. Su ingreso: S/4,298. El Hunter que espera, no cobra. El que caza, triunfa.', 7),
('El Pitch de 30 Segundos que Abre Puertas', 'El pitch de 30 segundos es la herramienta que engancha al cliente desde el primer momento. Debe ser breve, contundente y conectar con el dolor del cliente. No es una lista de características; es una declaración de valor que deja al cliente con una sola pregunta: "¿Cómo lo vemos?". El pitch debe memorizarse y adaptarse al contexto del cliente.', 'Un Hunter entra a un restaurante y dice: "INVU POS es el sistema operativo que usan más de 5,000 restaurantes en Latam. A diferencia de los POS locales, incluimos facturación electrónica nativa, llegamos llave en mano y te dejamos el restaurante operando desde el día uno. No vendemos un POS, vendemos una operación rentable." El dueño, que ha estado batallando con su facturación electrónica, responde: "¿Cómo lo vemos?" El Hunter ya tiene la reunión.', 8),
('Las 7 Preguntas del Hunter – El Mapa del Tesoro', 'El Hunter tiene 7 preguntas que revelan la calificación del cliente, sus dolores y los módulos que necesita. Sin estas preguntas, el Hunter está navegando sin mapa. Las preguntas cubren: facturación y sedes, sistema actual y dolor, facturación electrónica, recetas costeadas, número de cajas, delivery y ecommerce, y tomador de decisión y timeline.', 'En una primera reunión, el Hunter hace las 7 preguntas en 5 minutos. Descubre que el cliente tiene 3 sedes, paga Nubefact aparte, no tiene recetas costeadas, y quiere implementar QR y fidelización. El Hunter sabe exactamente qué cotizar: INVU Central + 3 licencias Sucursal + QR + Loyalty. El diagnóstico es el mapa; el cierre es el tesoro.', 9),
('La Facturación Electrónica Nativa – El Ahorro que el Cliente No Ve', 'El 70% de los restaurantes en Perú paga aparte por su facturación electrónica (S/89-149/mes). INVU incluye FE nativa sin límite de documentos. El Hunter debe mostrar que el costo de la competencia incluye un PSE externo que INVU ya tiene integrado. Cuando el cliente compara precios, el Hunter debe sumar ese costo oculto para mostrar el ahorro real.', 'Un cliente dice: "El POS X es más barato que INVU." El Hunter responde: "¿X incluye facturación electrónica nativa o pagas aparte a Nubefact o Efact?" El cliente admite que paga S/120/mes por Nubefact. El Hunter suma: "Entonces X te cuesta S/250 + S/120 + S/80 de soporte = S/450/mes. INVU es S/350/mes todo incluido. Termina siendo más barato." El cliente se queda pensando.', 10),
('Llave en Mano – La Implementación que Diferencia', 'INVU no entrega un software para que el cliente lo configure; lo deja operando. Configuración completa, carga de menú con recetas, instalación de equipos, capacitación y go live acompañado. La competencia vende licencias y deja solo al cliente. El Hunter debe comunicar que INVU no es un software; es una operación lista para facturar.', '"La competencia te vende licencias y te deja solo. INVU te deja el restaurante operando desde el día uno. Nosotros configuramos, cargamos tu menú con recetas y costos, instalamos equipos, capacitamos a tu personal y estamos contigo el día del arranque. No pagas por un software, pagas por una operación lista para facturar." El cliente, que no tiene tiempo para configurar sistemas, valora el servicio.', 11),
('Onboarding Consultivo – Costear para Ganar', 'INVU no solo enseña a usar el sistema; ayuda al cliente a montar una operación rentable: menú con recetas costeadas, materia prima, proveedores, márgenes reales por plato. Muchos dueños operan a ciegas: no saben cuánto ganan por plato, no controlan mermas. El onboarding consultivo transforma al vendedor en un asesor de confianza.', '"No solo te enseñamos a usar el sistema. Te ayudamos a montar tu operación para que sea rentable desde el día uno. Seteamos tu menú con recetas y costos reales, tu materia prima y proveedores. Así, cuando vendas un plato, sabes exactamente cuánto estás ganando. No más operar a ciegas." El dueño, que nunca ha visto el margen real de sus platos, percibe a INVU como un socio.', 12),
('Soporte Local 24/7 – El Seguro de Continuidad', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', 13),
('Ecosistema Móvil Nativo – El Negocio en el Bolsillo', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', 14),
('Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', 15)) AS t(concepto, enseñanza, ejemplo, orden);